/** Requisitions of one patient (newest first) — GET /api/v1/lab/requisitions (who may call: holders of lab.requisition.view or lab.result.view). */
export function listRequisitionsLab(query: { patient_id: number; limit?: number }): Promise<PatientRequisitionOut[]> {
  return api<PatientRequisitionOut[]>("GET", withQuery(`/lab/requisitions`, query), undefined);
}

/** Cancel tests not yet sampled (voids an unpaid lab bill) — POST /api/v1/lab/requisitions/{requisition_id}/cancel (who may call: holders of lab.requisition.cancel or lab.requisition.cancel_own). */
export function cancelRequisition(requisition_id: number, body: LabReasonIn): Promise<LabRequisitionDetailOut> {
  return api<LabRequisitionDetailOut>("POST", `/lab/requisitions/${requisition_id}/cancel`, body, { idempotent: true });
}

